look.customCSS:
/* ───── 圣诞 · 第一批 ───── */
/* 背景：深松绿，雪一直往下落；底下一片雪地小木屋常驻 */
[data-wk="chat"]{background:linear-gradient(180deg,#1A3329,#1E3B31 40%,#264A3D) !important;position:relative !important}
[data-wk="chat"]::before{content:"" !important;position:absolute !important;inset:0 !important;background:url("data:image/svg+xml;base64,") 0 0/180px 180px repeat,url("data:image/svg+xml;base64,") 60px 40px/260px 260px repeat !important;opacity:.9 !important;pointer-events:none !important;z-index:0 !important;animation:xmSnow 18s linear infinite !important}
@keyframes xmSnow{from{background-position:0 0,60px 40px}to{background-position:20px 180px,40px 300px}}
[data-wk="chat"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:0 !important;height:170px !important;background:url("data:image/svg+xml;base64,") center bottom/100% auto no-repeat !important;pointer-events:none !important;z-index:0 !important}
[data-wk="body"]{background:transparent !important;position:relative !important;z-index:1 !important;padding-top:58px !important}

/* 顶栏：圣诞红，下沿一圈雪帽，雪帽下挂一串彩灯 */
[data-wk="chathead"]{background:#B5383A !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;z-index:5 !important;overflow:visible !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:calc(100% - 1px) !important;height:52px !important;background:url("data:image/svg+xml;base64,") center top/100% auto no-repeat !important;pointer-events:none !important;animation:xmTwinkle 2.4s ease-in-out infinite !important}
@keyframes xmTwinkle{0%,100%{filter:brightness(1)}50%{filter:brightness(1.25) drop-shadow(0 0 4px rgba(255,230,150,.6))}}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important}
[data-wk="headdim"]{color:rgba(255,255,255,.75) !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#fff !important}
[data-wk="sameroom"]{width:34px !important;min-width:34px !important;height:34px !important;font-size:0 !important;padding:0 !important;background:url("data:image/svg+xml;base64,") center/30px 30px no-repeat !important;border:none !important;box-shadow:none !important}
[data-wk="chatmore"]{font-size:0 !important;color:transparent !important;width:42px !important;min-width:42px !important;height:30px !important;background:url("data:image/svg+xml;base64,") center/40px auto no-repeat !important;border:none !important;box-shadow:none !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
/* 顶栏头像戴一顶圣诞帽 */
[data-wk="chathead"] button:has(> [data-wk="avatar"]){position:relative !important;overflow:visible !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]) > [data-wk="avatar"]{box-shadow:0 0 0 2.5px #fff !important;border-radius:50% !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"])::before{content:"" !important;position:absolute !important;width:42px !important;height:32px !important;left:-2px !important;top:calc(50% - 34px) !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 1px #fff) drop-shadow(0 0 1px #fff) drop-shadow(0 2px 2px rgba(0,0,0,.25)) !important;transform:rotate(-16deg) !important;z-index:3 !important;pointer-events:none !important}

/* 头像：花环＋红蝴蝶结（垫在头像图底下，不挪头像位置） */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border-radius:50% !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{position:relative !important;z-index:1 !important;border-radius:50% !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;left:-22% !important;right:-22% !important;top:-22% !important;bottom:-40% !important;background:url("data:image/svg+xml;base64,") center top/contain no-repeat !important;z-index:0 !important;pointer-events:none !important}
[data-wk="chathead"] button[data-wk="avatar"]::before,[data-wk="chathead"] span[data-wk="avatar"]::before{content:none !important}

/* 我的话：红色雪帽气泡，左下角别一枝冬青 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#C8423F,#B5383A) !important;color:#fff !important;border:none !important;border-radius:22px 22px 8px 22px !important;box-shadow:0 3px 0 #8C2A2C !important;padding-top:16px !important;margin-top:10px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;left:-3px !important;right:-3px !important;top:-5px !important;height:20px !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;pointer-events:none !important;border:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;left:-12px !important;right:auto !important;bottom:-8px !important;width:32px !important;height:22px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:rotate(-12deg) !important}

/* 他的话：一张挂在灯串上的礼物卡——丝带往上吊，卡片轻轻晃，右下角一颗金星 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FFF8EA !important;color:#3A2A22 !important;border:1.5px solid #E8B85A !important;border-radius:6px 18px 18px 18px !important;box-shadow:0 4px 10px rgba(0,0,0,.25) !important;margin-top:26px !important;transform-origin:30px -26px !important;animation:xmSwing 4.5s ease-in-out infinite !important}
@keyframes xmSwing{0%,100%{transform:rotate(-1.2deg)}50%{transform:rotate(1.2deg)}}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;left:16px !important;top:-31px !important;width:30px !important;height:40px !important;background:url("data:image/svg+xml;base64,") center top/contain no-repeat !important;border:none !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;right:-8px !important;left:auto !important;bottom:-8px !important;width:18px !important;height:18px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important}
/* 连发：后面几张只用一截短丝带连在上一张底下，像一挂礼物卡 */
[data-first="0"] [data-wk="bubble"][data-kind="text"][data-me="0"]{margin-top:12px !important;animation:none !important}
[data-first="0"] [data-wk="bubble"][data-kind="text"][data-me="0"]::before{top:-34px !important;height:34px !important;z-index:-1 !important;width:4px !important;left:29px !important;background:#B5383A !important;border-radius:2px !important}
/* 我连发的第二条起不再顶雪，只第一条有 */
[data-first="0"] [data-wk="bubble"][data-kind="text"][data-me="1"]{padding-top:10px !important;margin-top:4px !important}
[data-first="0"] [data-wk="bubble"][data-kind="text"][data-me="1"]::before{display:none !important}

/* 时间：牛皮纸挂签；已读：一颗亮起来的小灯泡 */
[data-wk="time"] > span{background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important;border-radius:0 !important;padding:4px 16px 4px 24px !important;color:#6B4A2E !important;box-shadow:none !important}
[data-wk="meta"]{color:rgba(255,255,255,.75) !important}
[data-wk="meta"]::before{content:"" !important;display:inline-block !important;width:9px !important;height:13px !important;margin-right:4px !important;vertical-align:-2px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 3px rgba(242,193,78,.8)) !important}
[data-wk="typingdot"]{width:10px !important;height:14px !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFF8EA !important;border:1.5px solid #E8B85A !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
/* 动描、系统字：深底上用奶白小卡片垫着 */
[data-wk="narrink"]{background:rgba(255,248,234,.92) !important;border:1.5px dashed transparent !important;border-radius:14px !important;color:#3A2A22 !important;padding:4px 12px !important}
[data-wk="sysnotetext"]{color:rgba(255,255,255,.8) !important}
[data-wk="name"]{color:#fff !important}

/* 底栏：奶白胶囊把加号、输入、礼物、回复全包进去 */
[data-wk="composer"]{background:transparent !important;border-top:none !important;position:relative !important;z-index:2 !important;align-items:center !important;padding-left:16px !important;padding-right:16px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:6px !important;right:6px !important;top:2px !important;bottom:calc(env(safe-area-inset-bottom) * .4 + var(--composer-lift, 0px) - 8px) !important;border-radius:999px !important;background:#FFF8EA !important;border:2px solid #E8B85A !important;box-shadow:0 4px 0 #C9A46A !important;pointer-events:none !important;z-index:-1 !important}
[data-wk="chatinput"]{background:transparent !important;border:none !important;color:#3A2A22 !important}
[data-wk="chatinput"]::placeholder{color:#A8957A !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;width:34px !important;height:34px !important;min-width:34px !important;align-self:center !important;margin:0 !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA0MCA0MCc+PGNpcmNsZSBjeD0nMjAnIGN5PScyMCcgcj0nMTcnIGZpbGw9JyMzRTdBNTUnLz48cGF0aCBkPSdNMjAgMTIgVjI4IE0xMiAyMCBIMjgnIHN0cm9rZT0nI2ZmZicgc3Ryb2tlLXdpZHRoPSczJyBzdHJva2UtbGluZWNhcD0ncm91bmQnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.86) !important}
[data-wk="time"]{margin-top:26px !important}
[data-wk="chatpanel"]{background:#FFF8EA !important;position:relative !important;z-index:3 !important;border-top:2px solid #E8B85A !important}
/* 雪地小木屋抬到底栏上面露出来 */
[data-wk="chat"]::after{bottom:0 !important;height:calc(env(safe-area-inset-bottom) * .4 + 62px + 150px) !important;background:url("data:image/svg+xml;base64,") center bottom calc(env(safe-area-inset-bottom) * .4 + 60px)/100% auto no-repeat,linear-gradient(#F4F7F5,#F4F7F5) center bottom/100% calc(env(safe-area-inset-bottom) * .4 + 64px) no-repeat !important}
/* 回复键：帽子别顶出胶囊，跟发送键对齐 */
[data-wk="chatreply"]{background-size:88% !important;background-position:center 60% !important;margin-right:4px !important}
/* 他连发的一挂里，已读只留在最后一张底下，不让丝带穿过字 */
[data-wk="msg"][data-me="0"][data-last="0"] [data-wk="meta"]{display:none !important}

/* ───── 圣诞 · 第二批：卡片 ───── */
/* 卡片统一：奶白底、金边、底下一层暖棕影 */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="voice"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:#FFF8EA !important;border:1.8px solid #E8B85A !important;border-radius:18px !important;box-shadow:0 4px 0 #C9A46A,0 8px 18px rgba(0,0,0,.25) !important;color:#3A2A22 !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#3A2A22 !important;border-color:rgba(201,164,106,.5) !important}

/* 转账：一份包好的礼物——十字红丝带，收下盖金色火漆，退回盖灰的 */
[data-wk="transfercard"]{position:relative !important;overflow:visible !important;padding-top:28px !important;background:linear-gradient(90deg,transparent calc(100% - 46px),#B5383A calc(100% - 46px),#B5383A calc(100% - 36px),transparent calc(100% - 36px)),#FFF8EA !important}
[data-wk="transfercard"]::before{content:"✦ 圣诞礼单" !important;position:absolute !important;left:16px !important;top:9px !important;font-size:10px !important;letter-spacing:.2em !important;color:#B5383A !important}
[data-wk="transfercard"]::after{content:"" !important;position:absolute !important;right:22px !important;top:-14px !important;width:58px !important;height:30px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transferlabel"],[data-wk="transfernote"]::before{color:#8C6A3A !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#B5383A !important;font-weight:700 !important}
[data-wk="transferrule"]{border:none !important;height:2px !important;background:repeating-linear-gradient(90deg,#B5383A 0 10px,#fff 10px 14px,#3E7A55 14px 24px,#fff 24px 28px) !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:#F6EAD0 !important;border-radius:0 0 16px 16px !important}
[data-wk="transfernote"]::before{content:"贺词：" !important}
[data-wk="transferbtn"]{border-radius:999px !important}
[data-wk="transferbtn"][data-part="take"]{background:#B5383A !important;color:#fff !important;border:none !important;box-shadow:0 3px 0 #8C2A2C !important}
[data-wk="transferbtn"][data-part="back"]{background:#fff !important;color:#3E7A55 !important;border:1.5px solid #3E7A55 !important}
[data-wk="transferseal"]{border:1.8px solid #E8B85A !important;box-shadow:none !important;color:#8C6A3A !important;background:#fff !important;border-radius:50% !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"],[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"]{width:62px !important;height:62px !important;flex-shrink:0 !important;border:none !important;border-radius:0 !important;opacity:1 !important;transform:rotate(-10deg) !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 2px 2px rgba(0,0,0,.25)) !important}
[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"] *,[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"] *{display:none !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.85 !important}

/* 红包：挂一只圣诞袜，袜口露出礼物；领完了袜子空了 */
[data-wk="rpcard"]{background:#FFF8EA !important;border:1.8px solid #E8B85A !important;border-radius:18px !important;box-shadow:0 4px 0 #C9A46A,0 8px 18px rgba(0,0,0,.25) !important;padding-left:86px !important;min-height:96px !important;position:relative !important;overflow:visible !important}
[data-wk="rpcard"] *{color:#3A2A22 !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:14px !important;top:-10px !important;width:60px !important;height:74px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform-origin:50% 0 !important;animation:xmSwing 3s ease-in-out infinite !important}
[data-wk="rpcard"]::after{content:"圣诞袜" !important;position:absolute !important;left:26px !important;bottom:6px !important;font-size:10px !important;letter-spacing:.2em !important;color:#B5383A !important}
[data-wk="rpflap"],[data-wk="rpseal"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{background:#F3EDE0 !important;filter:none !important}
[data-wk="rpcard"][data-status="done"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;animation:none !important}
[data-wk="rpcard"][data-status="done"]::after{content:"掏空啦" !important}
[data-wk="rpenvelope"][data-stage="closed"]{background:url("data:image/svg+xml;base64,") 0 0/180px 180px,linear-gradient(180deg,#C8423F,#8C2A2C) !important;border:2px solid #E8B85A !important;border-radius:28px !important;box-shadow:0 10px 30px rgba(0,0,0,.35) !important}
[data-wk="rpenvelope"][data-stage="closed"] [data-wk="rparc"]{background:#1E3B31 !important;border-top:2px solid #E8B85A !important}
[data-wk="rpenvelope"][data-stage="closed"] *{color:#FFF1D6 !important}
[data-wk="rpopenbtn"]{background:#FFF8EA url("data:image/svg+xml;base64,") center/60% no-repeat !important;border:2.5px solid #E8B85A !important;box-shadow:0 4px 0 #B88A33 !important;animation:xmSwing 1.6s ease-in-out infinite !important}
[data-wk="rpopenbtn"],[data-wk="rpopenbtn"] *{color:transparent !important;font-size:0 !important}
[data-wk="rpenvelope"][data-stage="open"]{background:url("data:image/svg+xml;base64,") 0 0/180px 180px,linear-gradient(180deg,#1E3B31,#16302A) !important;border:2px solid #E8B85A !important;border-radius:28px !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rparc"][data-part="top"]{background:#B5383A !important;border-bottom:2px solid #E8B85A !important;box-shadow:none !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rparc"][data-part="top"]::after{content:none !important}
[data-wk="rpenvelope"][data-stage="open"] *{color:#FFF1D6 !important}
[data-wk="rpavatar"]{box-shadow:0 0 0 3px #FFF8EA,0 0 0 5px #E8B85A !important;border-radius:50% !important}
[data-wk="rpamount"]{color:#E8B85A !important;background:none !important}
[data-wk="rpclose"]{background:#FFF8EA !important;border:2px solid #E8B85A !important;color:#B5383A !important}

/* 照片：拍立得，右上角别一枝冬青 */
[data-wk="photocard"]{position:relative !important;overflow:visible !important;padding:8px 8px 22px !important}
[data-wk="photocard"]::after{content:"" !important;position:absolute !important;right:-10px !important;top:-10px !important;width:40px !important;height:28px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(20deg) !important}
[data-wk="photoface"]{background:url("data:image/svg+xml;base64,") 0 0/120px 120px,#1E3B31 !important;border-radius:10px !important;border:none !important}
[data-wk="photoface"] *,[data-wk="phototext"]{color:#FFF1D6 !important}
[data-wk="photocap"],[data-wk="photohint"]{color:#3A2A22 !important}
/* 语音：前面一颗会晃的金铃铛 */
[data-wk="voice"] > *{background:transparent !important;box-shadow:none !important;border:none !important;color:#3A2A22 !important}
[data-wk="voice"]{padding-left:40px !important;position:relative !important}
[data-wk="voice"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:22px !important;height:22px !important;margin-top:-12px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform-origin:50% 0 !important;animation:xmSwing 1.4s ease-in-out infinite !important;z-index:2 !important}
[data-wk="voicewave"] span{background:#B5383A !important}
/* 天气 */
[data-wk="wxcardsky"]{background:url("data:image/svg+xml;base64,") 0 0/120px 120px,linear-gradient(170deg,#264A3D,#1E3B31) !important}
[data-wk="wxcardsky"] *{color:#FFF1D6 !important}
[data-wk="wxcardsky"] svg{stroke:#E8B85A !important}
[data-wk="wxcardsay"]{background:#FFF8EA !important;color:#3A2A22 !important;border-top:1.5px solid #E8B85A !important}
/* 位置：一颗金星钉着 */
[data-wk="geopin"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;box-shadow:0 0 8px rgba(232,184,90,.8) !important;border:none !important;width:24px !important;height:24px !important;border-radius:0 !important}
[data-wk="geopin"] *{opacity:0 !important}
[data-wk="geopinstem"]{background:#E8B85A !important}
/* 名片 */
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 2px #FFF8EA,0 0 0 4px #3E7A55 !important}

/* 拍一拍：冬青小胶囊；通话结束胶囊同款 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;background:#FFF8EA url("data:image/svg+xml;base64,") 8px center/20px 14px no-repeat !important;border:1.5px solid #E8B85A !important;border-radius:999px !important;padding:3px 14px 3px 32px !important;color:#3A2A22 !important;box-shadow:0 2px 0 #C9A46A !important}
[data-wk="note"][data-part="call"] svg{stroke:#B5383A !important}
[data-wk="note"][data-part="callsum"]{color:rgba(255,255,255,.8) !important}
/* 系统提示：前面一朵雪花 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:rgba(0,0,0,.25) !important;border-radius:12px !important;padding:2px 10px !important;-webkit-box-decoration-break:clone !important;box-decoration-break:clone !important;line-height:2 !important}
