/* 线下小结：一张圣诞明信片——右上角贴邮票、盖一圈邮戳，标题是红丝带 */
[data-part="offlog"]{position:relative !important;overflow:visible !important;padding-top:26px !important;padding-right:64px !important;background:repeating-linear-gradient(180deg,transparent 0 27px,rgba(201,164,106,.25) 27px 28px),#FFF8EA !important}
[data-part="offlog"]::before{content:"" !important;position:absolute !important;right:12px !important;top:12px !important;width:40px !important;height:48px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(4deg) !important}
[data-part="offlog"]::after{content:"" !important;position:absolute !important;right:4px !important;top:40px !important;width:34px !important;height:34px !important;border:1.6px solid rgba(181,56,58,.55) !important;border-radius:50% !important;pointer-events:none !important}
[data-wk="offlogtitle"]{display:inline-block !important;position:absolute !important;top:-13px !important;left:16px !important;margin:0 !important;padding:4px 18px !important;background:#B5383A !important;color:#fff !important;border-radius:4px !important;letter-spacing:.12em !important;clip-path:polygon(0 0,100% 0,calc(100% - 8px) 50%,100% 100%,0 100%,8px 50%) !important}
[data-wk="offlogtitle"] *{color:#fff !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#B5383A !important}
[data-wk="offlogtranscript"]{border-top:1.5px solid rgba(201,164,106,.6) !important;color:#8C6A3A !important}

