[data-wk="chattoolicon"]::before{content:"" !important;position:absolute !important;left:50% !important;top:-7px !important;width:10px !important;height:8px !important;margin-left:-5px !important;background:#E8B85A !important;border-radius:2px 2px 0 0 !important}
